using System;
using System.Drawing;
using System.Drawing.Drawing2D;
using System.Windows.Forms;
namespace NightLens {
class AppButton:Button {
    protected override void OnPaint(PaintEventArgs e){e.Graphics.Clear(Parent?.BackColor??Style.Bg);if(Convert.ToString(Tag)=="gear"){e.Graphics.SmoothingMode=SmoothingMode.AntiAlias;float r=10,cx=Width/2f,cy=Height/2f;var points=new PointF[32];for(int i=0;i<32;i++){double angle=i*Math.PI/16;float radius=i%4==0||i%4==3?r*.76f:r;points[i]=new PointF(cx+(float)Math.Cos(angle)*radius,cy+(float)Math.Sin(angle)*radius);}using(var path=new GraphicsPath(FillMode.Alternate)){path.AddPolygon(points);path.AddEllipse(cx-r*.35f,cy-r*.35f,r*.7f,r*.7f);using(var brush=new SolidBrush(Style.Theme=="Night"?Style.Text:Color.FromArgb(205,146,12)))e.Graphics.FillPath(brush,path);}return;}
        using(var fill=new SolidBrush(Enabled?Style.Accent:Style.DisabledBg))e.Graphics.FillRectangle(fill,ClientRectangle);using(var border=new Pen(Enabled?Style.Accent:Style.Muted))e.Graphics.DrawRectangle(border,0,0,Width-1,Height-1);TextRenderer.DrawText(e.Graphics,Text,Font,ClientRectangle,Enabled?Style.ButtonText:Style.DisabledText,TextFormatFlags.HorizontalCenter|TextFormatFlags.VerticalCenter|TextFormatFlags.NoPrefix);if(Focused)ControlPaint.DrawFocusRectangle(e.Graphics,Rectangle.Inflate(ClientRectangle,-4,-4),Style.ButtonText,Style.Accent);
    }
    protected override void OnEnabledChanged(EventArgs e){base.OnEnabledChanged(e);Invalidate();}
}
static class Style {
    public static Color Bg=Color.FromArgb(235,240,246),Card=Color.White,Text=Color.FromArgb(24,39,57),Muted=Color.FromArgb(71,86,105),Accent=Color.FromArgb(41,77,116);
    public static Color ButtonText=Color.White,DisabledBg=Color.FromArgb(222,230,238),DisabledText=Color.FromArgb(65,81,101),BadgeBg=Color.FromArgb(197,237,214),BadgeText=Color.FromArgb(20,69,43);
    public static string Theme="Light";
    public static void SetTheme(string mode){Theme=mode=="Light"||mode=="Night"?mode:"Dark";if(Theme=="Light"){Bg=Color.FromArgb(226,232,240);Card=Color.FromArgb(249,251,253);Text=Color.FromArgb(24,39,57);Muted=Color.FromArgb(71,86,105);Accent=Color.FromArgb(41,77,116);ButtonText=Color.White;DisabledBg=Color.FromArgb(210,220,232);DisabledText=Color.FromArgb(65,81,101);BadgeBg=Color.FromArgb(197,237,214);BadgeText=Color.FromArgb(20,69,43);}else if(Theme=="Night"){Bg=Color.FromArgb(8,0,0);Card=Color.FromArgb(18,0,0);Text=Color.FromArgb(255,64,64);Muted=Color.FromArgb(225,52,52);Accent=Color.FromArgb(62,0,0);ButtonText=Color.FromArgb(255,85,85);DisabledBg=Color.FromArgb(30,0,0);DisabledText=Color.FromArgb(237,64,64);BadgeBg=Color.FromArgb(70,0,0);BadgeText=Color.FromArgb(255,100,100);}else{Bg=Color.FromArgb(24,30,39);Card=Color.FromArgb(36,45,57);Text=Color.FromArgb(237,242,248);Muted=Color.FromArgb(178,192,209);Accent=Color.FromArgb(61,96,138);ButtonText=Color.White;DisabledBg=Color.FromArgb(43,53,67);DisabledText=Color.FromArgb(170,186,205);BadgeBg=Color.FromArgb(41,83,61);BadgeText=Color.FromArgb(210,250,222);}}
    [System.Runtime.InteropServices.DllImport("dwmapi.dll")]static extern int DwmSetWindowAttribute(IntPtr handle,int attribute,ref int value,int size);
    static void TitleBar(Form form){if(!form.IsHandleCreated)return;try{int dark=Theme=="Light"?0:1;DwmSetWindowAttribute(form.Handle,20,ref dark,4);int bg=Bg.R|(Bg.G<<8)|(Bg.B<<16),fg=Text.R|(Text.G<<8)|(Text.B<<16);DwmSetWindowAttribute(form.Handle,35,ref bg,4);DwmSetWindowAttribute(form.Handle,36,ref fg,4);}catch{}}
    public static void Apply(Control root){if(root is DifficultyBadge){root.Invalidate();return;}if(root is Form){root.BackColor=Bg;root.ForeColor=Text;TitleBar((Form)root);}else if(root is TextBoxBase||root is NumericUpDown||root is ListBox||root is ComboBox){root.BackColor=Card;root.ForeColor=Text;}else if(root is AppButton){root.BackColor=Accent;root.ForeColor=ButtonText;}else if(root is Label||root is CheckBox){root.ForeColor=Text;if(root is CheckBox){var check=(CheckBox)root;check.FlatStyle=FlatStyle.Flat;check.FlatAppearance.BorderColor=Muted;check.FlatAppearance.CheckedBackColor=Accent;}}else if(root is RadioButton){root.ForeColor=Text;((RadioButton)root).FlatStyle=FlatStyle.Flat;}else if(root is TabPage){root.BackColor=Bg;root.ForeColor=Text;}if(root is DateTimePicker){var date=(DateTimePicker)root;date.CalendarMonthBackground=Card;date.CalendarForeColor=Text;date.CalendarTitleBackColor=Accent;date.CalendarTitleForeColor=ButtonText;}if(root is TabControl){var tabs=(TabControl)root;if(!Equals(tabs.Tag,"theme-tabs")){tabs.Tag="theme-tabs";tabs.DrawMode=TabDrawMode.OwnerDrawFixed;tabs.DrawItem+=(a,b)=>{using(var brush=new SolidBrush(b.Index==tabs.SelectedIndex?Accent:Card))b.Graphics.FillRectangle(brush,b.Bounds);TextRenderer.DrawText(b.Graphics,tabs.TabPages[b.Index].Text,tabs.Font,b.Bounds,b.Index==tabs.SelectedIndex?ButtonText:Text,TextFormatFlags.VerticalCenter|TextFormatFlags.HorizontalCenter);};}}foreach(Control child in root.Controls)Apply(child);root.Invalidate();}
    public static Label Label(string text,float size=10,bool bold=false){return new Label{Text=text,AutoSize=false,Dock=DockStyle.Fill,Font=new Font("Segoe UI",size,bold?FontStyle.Bold:FontStyle.Regular),ForeColor=Text,UseMnemonic=false,TextAlign=ContentAlignment.MiddleLeft,Padding=new Padding(0,1,0,2),Margin=new Padding(0),AutoEllipsis=true};}
    public static Button Button(string text,EventHandler action){var button=new AppButton{Text=text,AutoSize=false,Dock=DockStyle.Fill,Height=29,FlatStyle=FlatStyle.Flat,BackColor=Accent,ForeColor=Color.White,Padding=new Padding(2,0,2,0),Margin=new Padding(2)};button.FlatAppearance.BorderSize=0;button.Click+=action;return button;}
    public static ContextMenuStrip Menu(){return new ContextMenuStrip{BackColor=Card,ForeColor=Text,Renderer=new ThemeMenuRenderer()};}
    public static void Form(Form form){form.BackColor=Bg;form.ForeColor=Text;form.Font=new Font("Segoe UI",9.5f);form.AutoScaleMode=AutoScaleMode.Dpi;form.StartPosition=FormStartPosition.CenterScreen;form.Icon=Icon.ExtractAssociatedIcon(Application.ExecutablePath);form.ShowIcon=true;form.Shown+=(a,b)=>Apply(form);}
    public static TableLayoutPanel Grid(int columns,params float[] rows){var grid=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=columns,RowCount=rows.Length,Margin=new Padding(0),Padding=new Padding(0)};for(int i=0;i<columns;i++)grid.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100f/columns));foreach(var row in rows)grid.RowStyles.Add(new RowStyle(row<0?SizeType.Percent:SizeType.Absolute,row<0?-row:row));return grid;}
    public static Control Field(string title,Control input){var box=Grid(1,22,-100);box.Margin=new Padding(0,0,8,4);box.Controls.Add(Label(title,9.5f),0,0);input.Dock=DockStyle.Fill;input.Margin=new Padding(0);box.Controls.Add(input,0,1);return box;}
    public static ComboBox Combo(){return new ComboBox{DropDownStyle=ComboBoxStyle.DropDownList,BackColor=Card,ForeColor=Text,FlatStyle=FlatStyle.Flat,IntegralHeight=false,DropDownHeight=240};}
    public static void DarkCombo(ComboBox box){box.DrawMode=DrawMode.OwnerDrawFixed;box.Font=new Font("Segoe UI",9.5f);box.ItemHeight=(int)Math.Ceiling(box.Font.GetHeight())+5;box.FontChanged+=(s,e)=>{box.ItemHeight=(int)Math.Ceiling(box.Font.GetHeight())+5;};box.DrawItem+=(a,b)=>{bool selected=(b.State&DrawItemState.Selected)!=0;using(var brush=new SolidBrush(selected?Accent:Card))b.Graphics.FillRectangle(brush,b.Bounds);if(b.Index>=0)TextRenderer.DrawText(b.Graphics,box.GetItemText(box.Items[b.Index]),box.Font,b.Bounds,selected?ButtonText:Text,TextFormatFlags.VerticalCenter|TextFormatFlags.Left|TextFormatFlags.NoPrefix);b.DrawFocusRectangle();};}
    public static Control CardBox(string heading,string body,float bodySize=10){var box=Grid(1,27,-100);box.BackColor=Card;box.Padding=new Padding(9,4,9,5);box.Margin=new Padding(3);box.Controls.Add(Label(heading,10.5f,true),0,0);var label=Label(body,bodySize);label.TextAlign=ContentAlignment.TopLeft;box.Controls.Add(label,0,1);return box;}
    public static Control ObjectCard(string heading,string body,bool beginner){var box=Grid(1,28,-100);box.BackColor=Card;box.Padding=new Padding(9,4,9,5);box.Margin=new Padding(3);box.Tag="object-card";var header=Grid(beginner?2:1,-100);header.Controls.Add(Label(heading,10.5f,true),0,0);if(beginner){header.ColumnStyles[0].Width=100;header.ColumnStyles[1].SizeType=SizeType.Absolute;header.ColumnStyles[1].Width=143;header.Controls.Add(new DifficultyBadge{Dock=DockStyle.Fill,Margin=new Padding(4,2,0,2),AccessibleName="Beginner-friendly",Tag="beginner-badge"},1,0);}box.Controls.Add(header,0,0);var label=Label(body,9);label.TextAlign=ContentAlignment.TopLeft;box.Controls.Add(label,0,1);return box;}
    public static void FitScreen(Form form,int width,int height){var area=Screen.FromControl(form).WorkingArea;form.Size=new Size(Math.Min(width,area.Width-24),Math.Min(height,area.Height-24));form.MinimumSize=new Size(Math.Min(width,area.Width-24),Math.Min(height,area.Height-24));}
}
class DifficultyBadge:Control {
    public DifficultyBadge(){SetStyle(ControlStyles.UserPaint|ControlStyles.AllPaintingInWmPaint|ControlStyles.OptimizedDoubleBuffer,true);Font=new Font("Segoe UI",8.5f,FontStyle.Bold);}
    protected override void OnPaint(PaintEventArgs e){e.Graphics.SmoothingMode=SmoothingMode.AntiAlias;e.Graphics.Clear(Style.Card);using(var brush=new SolidBrush(Style.BadgeBg))e.Graphics.FillRectangle(brush,ClientRectangle);TextRenderer.DrawText(e.Graphics,"★ Beginner-friendly",Font,ClientRectangle,Style.BadgeText,TextFormatFlags.HorizontalCenter|TextFormatFlags.VerticalCenter|TextFormatFlags.NoPrefix);}
}
class ThemeDatePicker:DateTimePicker {
    public ThemeDatePicker(){SetStyle(ControlStyles.UserPaint|ControlStyles.OptimizedDoubleBuffer,true);}
    protected override void OnPaint(PaintEventArgs e){using(var brush=new SolidBrush(Style.Card))e.Graphics.FillRectangle(brush,ClientRectangle);using(var pen=new Pen(Style.Muted))e.Graphics.DrawRectangle(pen,0,0,Width-1,Height-1);TextRenderer.DrawText(e.Graphics,Value.ToString(CustomFormat),Font,new Rectangle(5,0,Width-24,Height),Style.Text,TextFormatFlags.VerticalCenter|TextFormatFlags.Left|TextFormatFlags.NoPrefix);using(var brush=new SolidBrush(Style.Text))e.Graphics.FillPolygon(brush,new[]{new Point(Width-16,Height/2-2),new Point(Width-8,Height/2-2),new Point(Width-12,Height/2+2)});}
    protected override void OnValueChanged(EventArgs e){base.OnValueChanged(e);Invalidate();}
}
class ThemeMenuRenderer:ToolStripProfessionalRenderer {
    protected override void OnRenderToolStripBackground(ToolStripRenderEventArgs e){using(var brush=new SolidBrush(Style.Card))e.Graphics.FillRectangle(brush,e.AffectedBounds);}
    protected override void OnRenderImageMargin(ToolStripRenderEventArgs e){using(var brush=new SolidBrush(Style.Card))e.Graphics.FillRectangle(brush,e.AffectedBounds);}
    protected override void OnRenderMenuItemBackground(ToolStripItemRenderEventArgs e){using(var brush=new SolidBrush(e.Item.Selected||e.Item.Pressed?Style.Accent:Style.Card))e.Graphics.FillRectangle(brush,new Rectangle(Point.Empty,e.Item.Size));}
    protected override void OnRenderItemText(ToolStripItemTextRenderEventArgs e){e.TextColor=!e.Item.Enabled?Style.DisabledText:e.Item.Selected?Style.ButtonText:Style.Text;base.OnRenderItemText(e);}
    protected override void OnRenderArrow(ToolStripArrowRenderEventArgs e){e.ArrowColor=Style.Text;base.OnRenderArrow(e);}
}
class SectionButton:AppButton {
    public bool Selected {get;set;}
    public SectionButton(){FlatStyle=FlatStyle.Flat;FlatAppearance.BorderSize=0;Font=new Font("Segoe UI",9.5f,FontStyle.Bold);}
    protected override void OnPaint(PaintEventArgs e){using(var brush=new SolidBrush(Selected?Style.Card:Style.Bg))e.Graphics.FillRectangle(brush,ClientRectangle);TextRenderer.DrawText(e.Graphics,Text,Font,ClientRectangle,Selected?Style.Text:Style.Muted,TextFormatFlags.VerticalCenter|TextFormatFlags.HorizontalCenter|TextFormatFlags.NoPrefix);if(Selected)using(var brush=new SolidBrush(Style.Theme=="Night"?Style.Text:Style.Accent))e.Graphics.FillRectangle(brush,0,Height-3,Width,3);if(Focused)ControlPaint.DrawFocusRectangle(e.Graphics,Rectangle.Inflate(ClientRectangle,-4,-5),Style.Text,Style.Card);}
}
}




